// --- Synthesis sink dispatch tests (CU10) ---

// stubCmdSynthesisProvider is a minimal SynthesisProvider for cmd-level tests.
type stubCmdSynthesisProvider struct {
	called bool
}

func (s *stubCmdSynthesisProvider) Synthesize(_ context.Context, _ string) (string, error) {
	s.called = true
	return "synthesis verdict", nil
}

// TestComposeMultiAgentSinks exercises the sink-composition helper directly
// with explicit isTTY/canPrompt values, so we get real coverage of the TTY
// branch without depending on os.Stdout being a terminal during `go test`.
func TestComposeMultiAgentSinks(t *testing.T) {
	t.Parallel()

	provider := &stubCmdSynthesisProvider{}
	noopCancel := func() {}

	tests := []struct {
		name      string
		isTTY     bool
		provider  review.SynthesisProvider
		wantTUI   bool
		wantDump  bool
		wantSynth bool
		wantTotal int
	}{
		{
			name:      "non-tty omits tui but auto-synthesizes with provider",
			isTTY:     false,
			provider:  provider,
			wantDump:  true,
			wantSynth: true,
			wantTotal: 2,
		},
		{
			name:      "tty with provider buffers dump and synth before the flusher",
			isTTY:     true,
			provider:  provider,
			wantTUI:   true,
			wantDump:  true,
			wantSynth: true,
			wantTotal: 4,
		},
		{
			name:      "tty without provider skips synth",
			isTTY:     true,
			provider:  nil,
			wantTUI:   true,
			wantDump:  true,
			wantTotal: 3,
		},
		{
			name:      "non-tty without provider is dump only",
			isTTY:     false,
			provider:  nil,
			wantDump:  true,
			wantTotal: 1,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			sinks := review.ExposedComposeMultiAgentSinks(review.SinkComposeInputs{
				Out:               &bytes.Buffer{},
				IsTTY:             tt.isTTY,
				AgentNames:        []string{"a", "b"},
				CancelRun:         noopCancel,
				SynthesisProvider: tt.provider,
			})
			if got := len(sinks); got != tt.wantTotal {
				t.Fatalf("len(sinks)=%d, want %d", got, tt.wantTotal)
			}
			_, hasTUI := review.ExposedFindTUISink(sinks)
			if hasTUI != tt.wantTUI {
				t.Errorf("findTUISink found=%v, want %v", hasTUI, tt.wantTUI)
			}
			var hasDump, hasSynth bool
			for _, s := range sinks {
				switch s.(type) {
				case review.DumpSink:
					hasDump = true
				case review.SynthesisSink:
					hasSynth = true
				}
			}
			if hasDump != tt.wantDump {
				t.Errorf("DumpSink present=%v, want %v", hasDump, tt.wantDump)
			}
			if hasSynth != tt.wantSynth {
				t.Errorf("SynthesisSink present=%v, want %v", hasSynth, tt.wantSynth)
			}
		})
	}
}

// TestComposeMultiAgentSinks_JudgeTimeoutWired proves the resolved --timeout
// value AND the synthesis-error callback reach the judge: composeMultiAgentSinks
// must set the SynthesisSink's ProviderTimeout from judgeTimeout and its OnError
// from onSynthesisError, in both the TTY and non-TTY paths. Without the former
// the judge would silently keep its own default regardless of --timeout; without
// the latter a failed judge could not surface in the command's exit status.
func TestComposeMultiAgentSinks_JudgeTimeoutWired(t *testing.T) {
	t.Parallel()

	provider := &stubCmdSynthesisProvider{}
	noopCancel := func() {}
	const want = 17 * time.Minute

	for _, isTTY := range []bool{false, true} {
		t.Run(map[bool]string{false: "non-tty", true: "tty"}[isTTY], func(t *testing.T) {
			t.Parallel()
			sinks := review.ExposedComposeMultiAgentSinks(review.SinkComposeInputs{
				Out:               &bytes.Buffer{},
				IsTTY:             isTTY,
				AgentNames:        []string{"a", "b"},
				CancelRun:         noopCancel,
				SynthesisProvider: provider,
				JudgeTimeout:      want,
				OnSynthesisError:  func(error) {},
			})
			var found bool
			for _, s := range sinks {
				if ss, ok := s.(review.SynthesisSink); ok {
					found = true
					if ss.ProviderTimeout != want {
						t.Errorf("SynthesisSink.ProviderTimeout = %v, want %v (judgeTimeout not wired)", ss.ProviderTimeout, want)
					}
					if ss.OnError == nil {
						t.Error("SynthesisSink.OnError is nil (onSynthesisError not wired) — a failed judge could not fail the command")
					}
				}
			}
			if !found {
				t.Fatal("no SynthesisSink composed")
			}
		})
	}
}

func TestComposeSingleAgentSinks(t *testing.T) {
